$result["txt"] = '';
$inFilter = "";
while($record = $button->getNextSelectedRecord()) {
  //  strrpos(string $haystack, string $needle, int $offset = 0): int|false
	if (strrpos($inFilter,$record["uid"]) > 0){
			continue;
  }
	$inFilter = "{$inFilter}'{$record["uid"]}',";	
}
if($inFilter == ""){
	//no data: Selecione um ou mais registros.
	$jsonData = array("message"=> "Selecione um ou mais registros.", "data" => null);
