	 { message: "", data: {workspace:"app", layerName: "geo_lote_31983", title: "Seleção (Lote)", style: { binValues: [{ alpha: 1, color: "#ff0000" }] }},  {fields:"uid", where: `"uid" in(1,4,2)`} } 
	*/	
  //cor fixa vermelho
	$paramTitle = "Seleção Loteamento";
	$paramColor = $params["style"]["color"];
	if($params["style"]["title"] != ""){
		$paramTitle = $params["style"]["title"];
	}
	if($params["style"]["color"] == ""){
		$paramColor = "#ff0000";
	}
	$jsonDataParamStyle =  array( "binValues" => [ array("alpha"=> 1, "color" => $paramColor )] );
	$jsonDataParamData = array( "workspace" => "app", "layerName" => "geo_loteamento", "title"=> $paramTitle, "style" => $jsonDataParamStyle);
	$inFilter = trim($inFilter, ",");
	/* $jsonDataParamData = array( "workspace" => "app", "layerName" => "geo_lote_31983", "title"=> $paramTitle); */
	$jsonDataParamFilter = array( "fields" => "uid", "where" => "\"uid\" in ({$inFilter})");
	$jsonData = array("message"=> "Localizado", "data" => [$jsonDataParamData , $jsonDataParamFilter]);	
	$result["txt"] = json_encode($jsonData);
}

